<script setup lang="ts">
/**
 * Switches between peer views of one subject (`design/components/tabs.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tabs.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, provide, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/tabs'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { Icon, agentMember, revealInline, useDirection, type IconRole } from '@polymorph/vue'
import styles from '@polymorph/recipes/overlays/tabs.module.css'
import Badge from '../structure/Badge.vue'

export type TabsOrientation = NonNullable<TabsProps['orientation']>

export interface TabDescriptor {
  value: string
  label: string
  icon?: IconRole
  count?: number
  disabled?: boolean
}

export interface TabsProps {
  defaultValue?: string
  /**
   * Keeps inactive panels mounted and `hidden` (Radix `forceMount`), so a form being edited or
   * an embedded player survives a tab switch. The default unmounts them, so the common case does
   * not pay to mount everything.
   */
  keepMounted?: boolean
  /**
   * Vertical is the same component on its side, with the rule down the start edge instead of
   * along the bottom. Use it when labels are long enough that a horizontal strip would wrap,
   * because wrapped tabs no longer read as peers.
   */
  orientation?: 'horizontal' | 'vertical'
  tabs: TabDescriptor[]
  value?: string
}

defineOptions({ name: 'Tabs', inheritAttrs: false })

const props = withDefaults(defineProps<TabsProps>(), {
  keepMounted: false,
  orientation: 'horizontal',
})
const emit = defineEmits<{ change: [value: string] }>()
defineSlots<{ default: (props: Record<string, never>) => unknown }>()
const uid = useId()
const list = useTemplateRef<HTMLElement>('list')
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    value: props.value,
    defaultValue: props.defaultValue ?? props.tabs[0]?.value,
    orientation: props.orientation,
    onValueChange: (details) => {
      emit('change', details.value)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
provide('polymorph:Tabs', {
  get api() {
    return api.value
  },
  get keepMounted() {
    return props.keepMounted
  },
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    revealInline(list.value, list.value?.querySelector('[data-state="active"]'), true)
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [list.value]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
const effect2 = () => {
  revealInline(list.value, list.value?.querySelector('[data-state="active"]'))
}
watch(() => api.value.value, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'Tabs',
    element: () => list.value,
    state: () => ({
      value: api.value.value ?? null,
      tabs: props.tabs.map((tab) => ({
        id: tab.value,
        label: tab.label,
        ...(tab.disabled === true ? { disabled: true } : {}),
      })),
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) => value === api.value.value || api.value.setValue(value),
      },
    },
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <div v-bind="api.getRootProps()" :class="styles.root" data-member="tabs">
    <!-- list -->
    <div ref="list" v-bind="api.getListProps()" :class="styles.list" data-tabs-part="list">
      <template v-for="tab in tabs" :key="tab.value">
        <!-- tab -->
        <button
          v-bind="api.getTriggerProps({ value: tab.value, disabled: tab.disabled })"
          :class="styles.trigger"
          data-tabs-part="tab"
          :data-state="api.value === tab.value ? 'active' : 'inactive'"
          :data-disabled="tab.disabled ? '' : undefined"
        >
          <span v-if="tab.icon !== undefined" :class="styles.glyph">
            <Icon :name="tab.icon" size="sm" />
          </span>
          <span>
            {{ tab.label }}
          </span>
          <span v-if="tab.count !== undefined" :class="styles.count">
            <Badge :tone="api.value === tab.value ? 'accent' : 'neutral'">
              {{ String(tab.count) }}
            </Badge>
          </span>
        </button>
      </template>
      <!-- indicator -->
      <div
        v-bind="api.getIndicatorProps()"
        :class="[styles.indicator, styles.slide]"
        :style="{
          inlineSize:
            orientation === 'vertical'
              ? undefined
              : Object(api.getIndicatorProps().style)['--width'],
          blockSize:
            orientation === 'vertical'
              ? Object(api.getIndicatorProps().style)['--height']
              : undefined,
        }"
      />
    </div>
    <slot />
  </div>
</template>
